configuration.jsScript:
var t = msg.temperature != null ? Double.parseDouble(msg.temperature.toString()) : null;
if (t == null) {
    return {msg: msg, metadata: metadata, msgType: msgType};
}

var ll = metadata.ss_alarm_LL != null ? Double.parseDouble(metadata.ss_alarm_LL.toString()) : 5.0;
var l  = metadata.ss_alarm_L  != null ? Double.parseDouble(metadata.ss_alarm_L.toString())  : 12.0;
var h  = metadata.ss_alarm_H  != null ? Double.parseDouble(metadata.ss_alarm_H.toString())  : 38.0;
var hh = metadata.ss_alarm_HH != null ? Double.parseDouble(metadata.ss_alarm_HH.toString()) : 45.0;

msg.alarm_LL = ll;
msg.alarm_L  = l;
msg.alarm_H  = h;
msg.alarm_HH = hh;

if (t <= ll) {
    msg.alarmLevel = "LL (Quá Lạnh Khẩn Cấp <= " + ll + "°C)";
    msg.alarmCode = "TEMP_LOW_LOW";
    msg.alarmSeverity = "CRITICAL";
    msg.thresholdValue = ll;
    msg.currentTemp = t;
    metadata.alarmSeverity = "CRITICAL";
} else if (t >= hh) {
    msg.alarmLevel = "HH (Quá Nóng Khẩn Cấp >= " + hh + "°C)";
    msg.alarmCode = "TEMP_HIGH_HIGH";
    msg.alarmSeverity = "CRITICAL";
    msg.thresholdValue = hh;
    msg.currentTemp = t;
    metadata.alarmSeverity = "CRITICAL";
} else if (t <= l) {
    msg.alarmLevel = "L (Cảnh Báo Thấp <= " + l + "°C)";
    msg.alarmCode = "TEMP_LOW";
    msg.alarmSeverity = "WARNING";
    msg.thresholdValue = l;
    msg.currentTemp = t;
    metadata.alarmSeverity = "WARNING";
} else if (t >= h) {
    msg.alarmLevel = "H (Cảnh Báo Cao >= " + h + "°C)";
    msg.alarmCode = "TEMP_HIGH";
    msg.alarmSeverity = "WARNING";
    msg.thresholdValue = h;
    msg.currentTemp = t;
    metadata.alarmSeverity = "WARNING";
} else {
    msg.alarmLevel = null;
    msg.alarmCode = null;
    msg.alarmSeverity = null;
}

return {msg: msg, metadata: metadata, msgType: msgType};

